#!/usr/bin/env node
'use strict';

// extract.js <elf-binary>
//
// Extracts 4-byte little-endian unsigned words at 4-byte aligned virtual
// addresses from every PT_LOAD segment of an ELF64 file, and emits them as a
// JSON object { "<vaddr-decimal>": <uint32-value>, ... }.
//
// The file image bytes (p_filesz) are read directly; the .bss tail
// (p_memsz - p_filesz) is zero-filled, since .bss is zero-initialized.

const fs = require('fs');

const file = process.argv[2];
if (!file) {
  process.stderr.write('usage: node extract.js <elf-binary>\n');
  process.exit(1);
}

const buf = fs.readFileSync(file);

// --- ELF64 header ---
const EI_MAG = buf.slice(0, 4);
if (EI_MAG[0] !== 0x7f || EI_MAG[1] !== 0x45 || EI_MAG[2] !== 0x4c || EI_MAG[3] !== 0x46) {
  process.stderr.write('not an ELF file\n');
  process.exit(1);
}
const EI_CLASS = buf[4]; // 1 = ELF32, 2 = ELF64
if (EI_CLASS !== 2) {
  process.stderr.write('only ELF64 supported\n');
  process.exit(1);
}
const EI_DATA = buf[5]; // 1 = little-endian
if (EI_DATA !== 1) {
  process.stderr.write('only little-endian supported\n');
  process.exit(1);
}

const e_phoff   = buf.readUInt32LE(32) + buf.readUInt32LE(36) * 0x100000000; // 64-bit
const e_phentsize = buf.readUInt16LE(54);
const e_phnum    = buf.readUInt16LE(56);

const PT_LOAD = 1;

const result = {};

for (let i = 0; i < e_phnum; i++) {
  const off = e_phoff + i * e_phentsize;
  const p_type   = buf.readUInt32LE(off + 0);
  if (p_type !== PT_LOAD) continue;

  const p_offset = buf.readUInt32LE(off + 8)  + buf.readUInt32LE(off + 12) * 0x100000000;
  const p_vaddr  = buf.readUInt32LE(off + 16) + buf.readUInt32LE(off + 20) * 0x100000000;
  const p_filesz = buf.readUInt32LE(off + 32) + buf.readUInt32LE(off + 36) * 0x100000000;
  const p_memsz  = buf.readUInt32LE(off + 40) + buf.readUInt32LE(off + 44) * 0x100000000;

  // File-backed bytes: complete 4-byte words at 4-byte alignment.
  const fileWords = Math.floor(p_filesz / 4);
  for (let w = 0; w < fileWords; w++) {
    const addr = p_vaddr + w * 4;
    const foff = p_offset + w * 4;
    const value = buf.readUInt32LE(foff);
    result[addr] = value;
  }

  // Zero-filled .bss tail (memsz - filesz), complete 4-byte words.
  const bssBytes = p_memsz - p_filesz;
  const bssWords = Math.floor(bssBytes / 4);
  for (let w = 0; w < bssWords; w++) {
    const addr = p_vaddr + p_filesz + w * 4;
    result[addr] = 0;
  }
}

process.stdout.write(JSON.stringify(result) + '\n');

