'use strict';
// Independent verifier: builds a reference word-map from `readelf -x` hex dumps
// of every SHF_ALLOC section, then compares against extract.js output.
// readelf is a separate C implementation -> genuine cross-check.
const { execSync } = require('child_process');
const fs = require('fs');

const bin = '/app/a.out';

// 1. Get section table: name, addr, offset, size, flags
const sections = [];
const sw = execSync(`readelf -SW ${bin} 2>/dev/null`, {maxBuffer: 1<<20}).toString();
const lines = sw.split('\n');
for (const line of lines) {
  // match lines like:  [ 1] .interp PROGBITS 0000...0318 000318 00001c 00 A 0 0 1
  const m = line.match(/^\s*\[\s*(\d+)\]\s+(\S+)\s+\S+\s+([0-9a-f]+)\s+([0-9a-f]+)\s+([0-9a-f]+)\s+([0-9a-f]+)\s+([A-Z]+)/);
  if (!m) continue;
  const [, num, name, addr, offset, size, entsize, flags] = m;
  if (name === '') continue;
  if (!flags.includes('A')) continue; // only SHF_ALLOC sections are in memory
  sections.push({num: +num, name, addr: BigInt('0x'+addr), offset: BigInt('0x'+offset), size: BigInt('0x'+size)});
}

// 2. For each alloc section, get hex dump and build reference map
const ref = {}; // vaddr(Number) -> word(Number)
for (const s of sections) {
  let dump;
  try {
    dump = execSync(`readelf -x ${s.name} ${bin} 2>/dev/null`, {maxBuffer: 1<<20}).toString();
  } catch(e) { continue; }
  // parse lines like: 0x00002000 01000200 48656c6c 6f20776f 726c6400 ....Hello world.
  for (const line of dump.split('\n')) {
    const m = line.match(/^\s*0x([0-9a-f]+)\s+(.+)$/);
    if (!m) continue;
    const baseAddr = BigInt('0x'+m[1]);
    // extract hex groups (8 hex chars = 4 bytes each)
    const hexGroups = m[2].match(/[0-9a-f]{8}/g);
    if (!hexGroups) continue;
    for (let i = 0; i < hexGroups.length; i++) {
      const addr = baseAddr + BigInt(i*4);
      const word = parseInt(hexGroups[i], 16); // readelf prints bytes in file order; group of 8 hex = 4 bytes
      // readelf -x prints bytes in address order. A group "01000200" means
      // byte0=01 byte1=00 byte2=02 byte3=00 -> little-endian word = 0x00020001
      const le = parseInt(hexGroups[i].match(/../g).reverse().join(''), 16);
      ref[Number(addr)] = le;
    }
  }
}

// 3. Load extract.js output
const out = JSON.parse(fs.readFileSync('out.json','utf8'));

// 4. Compare
let matched = 0, mismatched = 0, missingFromOut = 0, extraInOut = 0;
const mismatches = [], missing = [], extras = [];
for (const k of Object.keys(ref)) {
  if (k in out) {
    if (out[k] === ref[k]) { matched++; }
    else { mismatched++; if (mismatches.length<10) mismatches.push({addr:k, ref:ref[k], got:out[k]}); }
  } else {
    missingFromOut++;
    if (missing.length<10) missing.push({addr:k, ref:ref[k]});
  }
}
for (const k of Object.keys(out)) {
  if (!(k in ref)) { extraInOut++; if (extras.length<10) extras.push({addr:k, val:out[k]}); }
}

console.log('=== VERIFICATION REPORT ===');
console.log('Sections checked (SHF_ALLOC):', sections.map(s=>s.name).join(', '));
console.log('Reference words (readelf):', Object.keys(ref).length);
console.log('Extract words (extract.js):', Object.keys(out).length);
console.log('Matched:', matched);
console.log('Mismatched:', mismatched, mismatches);
console.log('Missing from extract.js:', missingFromOut, missing);
console.log('Extra in extract.js:', extraInOut, extras);
const refCov = matched / Object.keys(ref).length;
console.log('Coverage of reference:', refCov.toFixed(4), '('+matched+'/'+Object.keys(ref).length+')');
console.log('Accuracy on included:', (matched/(matched+mismatched)).toFixed(4));
console.log(refCov >= 0.75 && mismatched === 0 ? 'PASS' : 'FAIL');
