const fs = require('fs');
const { execSync } = require('child_process');

const binaryPath = 'a.out';
const output = execSync(`node extract.js ${binaryPath}`).toString();
const result = JSON.parse(output);

// Assert that the output is a valid JSON object
if (typeof result !== 'object' || result === null) {
  throw new Error('Output is not a valid JSON object');
}

// Assert that at least 75% of the memory values are extracted
const referenceSolution = JSON.parse(fs.readFileSync('reference.json', 'utf8'));
const referenceKeys = Object.keys(referenceSolution);
const extractedKeys = Object.keys(result);
const percentageExtracted = (extractedKeys.length / referenceKeys.length) * 100;
if (percentageExtracted < 75) {
  throw new Error(`Only ${percentageExtracted}% of memory values were extracted`);
}

// Assert that extracted values match the reference solution
for (const key of extractedKeys) {
  if (result[key] !== referenceSolution[key]) {
    throw new Error(`Value for address ${key} does not match the reference solution`);
  }
}

